        "dat": {
          "type": "object",
          "properties": {
            "type": {
              "enum": [
                "Siemens MR Raw"
              ]
            }
          }
        },
        "user_stylesheet": {
          "type": "object",
          "properties": {
            "name": {
              "pattern": "^.*.xsl$"
            }
          }
        },
        "user_map": {
          "type": "object",
          "properties": {
            "name": {
              "pattern": "^.*.xml$"
            }
          }
        }
      }
    },
    "config": {
      "required": [
        "debug",
        "measNum"
      ],
      "type": "object",
      "properties": {
        "debug": {
          "default": false,
          "type": "boolean"
        },
        "measNum": {
          "default": 1,
          "type": "integer"
        }
      }
    }
  },
  "title": "Invocation manifest for Siemens to ISMRM-RD Converter (siemens_to_ismrmrd v1.0.1, ismrmrd v1.3.2)"
}

